1	#!/usr/bin/env node
2	'use strict';
3	
4	const fs = require('fs');
5	const os = require('os');
6	const path = require('path');
7	const { execSync } = require('child_process');
8	
9	const DEFAULT_CACHE_TTL_MS = 60_000;
10	const DEFAULT_FETCH_TIMEOUT_MS = 5_000;
11	const DEFAULT_USER_AGENT = 'claudekit-engineer/1.0';
12	const DEFAULT_ELIGIBILITY_CACHE_TTL_MS = 60_000;
13	
14	function getUsageCachePath() {
15	  return process.env.CK_USAGE_CACHE_PATH || path.join(os.tmpdir(), 'ck-usage-limits-cache.json');
16	}
17	
18	function getQuotaEligibilityCachePath() {
19	  return process.env.CK_USAGE_ELIGIBILITY_CACHE_PATH || `${getUsageCachePath()}.eligibility`;
20	}
21	
22	function readUsageCache(cachePath = getUsageCachePath()) {
23	  try {
24	    if (!fs.existsSync(cachePath)) return null;
25	    const parsed = JSON.parse(fs.readFileSync(cachePath, 'utf8'));
26	    return parsed && typeof parsed === 'object' ? parsed : null;
27	  } catch {
28	    return null;
29	  }
30	}
31	
32	function getCacheAgeMs(cache, now = Date.now()) {
33	  if (!cache || typeof cache.timestamp !== 'number') return Number.POSITIVE_INFINITY;
34	  return Math.max(0, now - cache.timestamp);
35	}
36	
37	function isUsageCacheFresh(cache, maxAgeMs, now = Date.now()) {
38	  return getCacheAgeMs(cache, now) <= maxAgeMs;
39	}
40	
41	function normalizeUtilization(utilization) {
42	  if (typeof utilization !== 'number' || !Number.isFinite(utilization)) return null;
43	  if (utilization > 0 && utilization < 1) return Math.round(utilization * 100);
44	  return Math.max(0, Math.round(utilization));
45	}
46	
47	function buildUsageSnapshot(data = null, now = Date.now()) {
48	  if (!data || typeof data !== 'object') return null;
49	
50	  return {
51	    sourceVersion: 1,
52	    fetchedAt: new Date(now).toISOString(),
53	    fiveHourPercent: normalizeUtilization(data.five_hour?.utilization),
54	    weekPercent: normalizeUtilization(data.seven_day?.utilization)
55	  };
56	}
57	
58	function writeUsageCache(status, data = null, { cachePath = getUsageCachePath(), now = Date.now() } = {}) {
59	  const tmpFile = `${cachePath}.${process.pid}.${now}.${Math.random().toString(16).slice(2)}.tmp`;
60	  const snapshot = status === 'available' ? buildUsageSnapshot(data, now) : null;
61	
62	  try {
63	    fs.writeFileSync(
64	      tmpFile,
65	      JSON.stringify({
66	        timestamp: now,
67	        status,
68	        data,
69	        snapshot
70	      })
71	    );
72	    fs.renameSync(tmpFile, cachePath);
73	  } catch {
74	    try { fs.unlinkSync(tmpFile); } catch {}
75	  }
76	}
77	
78	function readQuotaEligibilityCache(cachePath = getQuotaEligibilityCachePath()) {
79	  try {
80	    if (!fs.existsSync(cachePath)) return null;
81	    const parsed = JSON.parse(fs.readFileSync(cachePath, 'utf8'));
82	    if (parsed && typeof parsed === 'object' && typeof parsed.eligible === 'boolean') {
83	      return parsed;
84	    }
85	  } catch {}
86	  return null;
87	}
88	
89	function writeQuotaEligibilityCache(result, { cachePath = getQuotaEligibilityCachePath(), now = Date.now() } = {}) {
90	  if (!result || typeof result.eligible !== 'boolean') return;
91	
92	  const tmpFile = `${cachePath}.${process.pid}.${now}.${Math.random().toString(16).slice(2)}.tmp`;
93	  try {
94	    fs.writeFileSync(
95	      tmpFile,
96	      JSON.stringify({
97	        timestamp: now,
98	        eligible: result.eligible,
99	        note: result.note || null
100	      })
101	    );
102	    fs.renameSync(tmpFile, cachePath);
103	  } catch {
104	    try { fs.unlinkSync(tmpFile); } catch {}
105	  }
106	}
107	
108	function hasAnthropicRuntimeOverride(envObj = process.env) {
109	  return ['ANTHROPIC_BASE_URL', 'ANTHROPIC_AUTH_TOKEN', 'ANTHROPIC_API_KEY']
110	    .some((key) => typeof envObj?.[key] === 'string' && envObj[key].trim() !== '');
111	}
112	
113	function readClaudeCredentials({
114	  platform = os.platform(),
115	  homedir = os.homedir(),
116	  execSyncImpl = execSync
117	} = {}) {
118	  if (platform === 'darwin') {
119	    try {
120	      const raw = execSyncImpl('security find-generic-password -s "Claude Code-credentials" -w', {
121	        timeout: 5_000,
122	        encoding: 'utf8',
123	        stdio: ['pipe', 'pipe', 'ignore']
124	      }).trim();
125	      const parsed = JSON.parse(raw);
126	      if (parsed && typeof parsed === 'object') return parsed;
127	    } catch {}
128	  }
129	
130	  try {
131	    const credentialsPath = path.join(homedir, '.claude', '.credentials.json');
132	    const parsed = JSON.parse(fs.readFileSync(credentialsPath, 'utf8'));
133	    return parsed && typeof parsed === 'object' ? parsed : null;
134	  } catch {
135	    return null;
136	  }
137	}
138	
139	function getClaudeAccessTokenFromCredentials(credentials) {
140	  return credentials?.claudeAiOauth?.accessToken || null;
141	}
142	
143	function hasSupportedClaudeSubscription(credentials) {
144	  const subscriptionType = String(credentials?.claudeAiOauth?.subscriptionType || '').trim().toLowerCase();
145	  if (subscriptionType && subscriptionType !== 'free' && subscriptionType !== 'none') return true;
146	
147	  const rateLimitTier = String(credentials?.claudeAiOauth?.rateLimitTier || '').trim().toLowerCase();
148	  return /claude|max|pro|team|enterprise/.test(rateLimitTier);
149	}
150	
151	function resolveQuotaDisplayEligibility(options = {}) {
152	  if (hasAnthropicRuntimeOverride(options.env)) {
153	    return { eligible: false, note: 'runtime-override', accessToken: null };
154	  }
155	
156	  const explicitAccessToken = typeof options.accessToken === 'string' && options.accessToken.trim() !== '';
157	  const explicitCredentials = Object.prototype.hasOwnProperty.call(options, 'credentials');
158	
159	  if (options.useCache && !explicitAccessToken && !explicitCredentials) {
160	    const cached = readQuotaEligibilityCache(options.eligibilityCachePath);
161	    if (isUsageCacheFresh(cached, options.eligibilityCacheTtlMs || DEFAULT_ELIGIBILITY_CACHE_TTL_MS, options.now)) {
162	      return { eligible: cached.eligible, note: cached.note || 'cached', accessToken: null };
163	    }
164	  }
165	
166	  const credentials = explicitCredentials ? options.credentials : readClaudeCredentials(options);
167	
168	  let result;
169	  if (explicitAccessToken) {
170	    result = credentials && !hasSupportedClaudeSubscription(credentials)
171	      ? { eligible: false, note: 'non-subscription-auth', accessToken: null }
172	      : { eligible: true, note: 'eligible', accessToken: options.accessToken.trim() };
173	  } else {
174	    const accessToken = getClaudeAccessTokenFromCredentials(credentials);
175	    if (!accessToken) {
176	      result = { eligible: false, note: 'missing-credentials', accessToken: null };
177	    } else if (!hasSupportedClaudeSubscription(credentials)) {
178	      result = { eligible: false, note: 'non-subscription-auth', accessToken: null };
179	    } else {
180	      result = { eligible: true, note: 'eligible', accessToken };
181	    }
182	  }
183	
184	  if (options.useCache && !explicitAccessToken && !explicitCredentials) {
185	    writeQuotaEligibilityCache(result, {
186	      cachePath: options.eligibilityCachePath,
187	      now: options.now
188	    });
189	  }
190	
191	  return result;
192	}
193	
194	function getClaudeAccessToken(options = {}) {
195	  return resolveQuotaDisplayEligibility(options).accessToken;
196	}
197	
198	async function fetchUsageLimits(options = {}) {
199	  const {
200	  fetchImpl = fetch,
201	  fetchTimeoutMs = DEFAULT_FETCH_TIMEOUT_MS,
202	  userAgent = DEFAULT_USER_AGENT,
203	  accessToken
204	  } = options;
205	  const eligibility = resolveQuotaDisplayEligibility({ ...options, accessToken });
206	  const token = eligibility.accessToken;
207	  if (!eligibility.eligible || !token) {
208	    return {
209	      ok: false,
210	      cacheStatus: 'unavailable',
211	      note: eligibility.note || 'missing-credentials',
212	      data: null
213	    };
214	  }
215	
216	  const controller = typeof AbortController === 'function' ? new AbortController() : null;
217	  const timeoutId = controller
218	    ? setTimeout(() => controller.abort(), fetchTimeoutMs)
219	    : null;
220	
221	  try {
222	    const response = await fetchImpl('https://api.anthropic.com/api/oauth/usage', {
223	      method: 'GET',
224	      headers: {
225	        Accept: 'application/json',
226	        'Content-Type': 'application/json',
227	        Authorization: `Bearer ${token}`,
228	        'anthropic-beta': 'oauth-2025-04-20',
229	        'User-Agent': userAgent
230	      },
231	      signal: controller?.signal
232	    });
233	
234	    if (!response.ok) {
235	      return { ok: false, cacheStatus: 'unavailable', note: `http-${response.status}`, data: null };
236	    }
237	
238	    const data = await response.json();
239	    if (!data || typeof data !== 'object') {
240	      return { ok: false, cacheStatus: 'unavailable', note: 'invalid-body', data: null };
241	    }
242	
243	    return { ok: true, cacheStatus: 'available', note: 'fetched', data };
244	  } catch (error) {
245	    const note = error?.name === 'AbortError' ? 'timeout' : 'fetch-failed';
246	    return { ok: false, cacheStatus: 'unavailable', note, data: null };
247	  } finally {
248	    if (timeoutId) clearTimeout(timeoutId);
249	  }
250	}
251	
252	async function refreshUsageCache(options = {}) {
253	  const result = await fetchUsageLimits(options);
254	  writeUsageCache(result.cacheStatus, result.data, options);
255	
256	  return {
257	    ...result,
258	    cache: readUsageCache(options.cachePath)
259	  };
260	}
261	
262	module.exports = {
263	  DEFAULT_CACHE_TTL_MS,
264	  DEFAULT_FETCH_TIMEOUT_MS,
265	  DEFAULT_ELIGIBILITY_CACHE_TTL_MS,
266	  getUsageCachePath,
267	  getQuotaEligibilityCachePath,
268	  readUsageCache,
269	  readQuotaEligibilityCache,
270	  getCacheAgeMs,
271	  isUsageCacheFresh,
272	  buildUsageSnapshot,
273	  writeUsageCache,
274	  writeQuotaEligibilityCache,
275	  hasAnthropicRuntimeOverride,
276	  readClaudeCredentials,
277	  hasSupportedClaudeSubscription,
278	  resolveQuotaDisplayEligibility,
279	  getClaudeAccessToken,
280	  fetchUsageLimits,
281	  refreshUsageCache,
282	  normalizeUtilization
283	};
