1	/**
2	 * Analytics Library
3	 *
4	 * Track and aggregate revenue metrics across channels.
5	 *
6	 * Required env: STRIPE_SECRET_KEY (for Stripe revenue)
7	 */
8	
9	import fs from 'fs/promises';
10	import path from 'path';
11	
12	const DATA_DIR = 'data/analytics';
13	const MANUAL_REVENUE_FILE = 'manual-revenue.json';
14	
15	/**
16	 * Revenue channel configurations
17	 */
18	const CHANNELS = {
19	  stripe: {
20	    name: 'Stripe Products',
21	    source: 'api',
22	    async getRevenue(period) {
23	      return await getStripeRevenue(period);
24	    }
25	  },
26	  payhip: {
27	    name: 'Payhip',
28	    source: 'manual',
29	    async getRevenue(period) {
30	      return await getManualRevenue('payhip', period);
31	    }
32	  },
33	  promptbase: {
34	    name: 'PromptBase',
35	    source: 'manual',
36	    async getRevenue(period) {
37	      return await getManualRevenue('promptbase', period);
38	    }
39	  }
40	};
41	
42	/**
43	 * Get Stripe revenue for period
44	 */
45	async function getStripeRevenue(period = 'month') {
46	  if (!process.env.STRIPE_SECRET_KEY) {
47	    return { revenue: 0, transactions: 0, error: 'STRIPE_SECRET_KEY not set' };
48	  }
49	
50	  const Stripe = (await import('stripe')).default;
51	  const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
52	
53	  const now = Math.floor(Date.now() / 1000);
54	  const periods = {
55	    today: now - 86400,
56	    week: now - 604800,
57	    month: now - 2592000,
58	    all: 0
59	  };
60	
61	  const created = periods[period] || periods.month;
62	
63	  const charges = await stripe.charges.list({
64	    created: { gte: created },
65	    limit: 100
66	  });
67	
68	  const successful = charges.data.filter(c => c.status === 'succeeded');
69	  const revenue = successful.reduce((sum, c) => sum + c.amount, 0);
70	
71	  return {
72	    revenue: revenue / 100,
73	    transactions: successful.length,
74	    avg_order: successful.length > 0 ? revenue / 100 / successful.length : 0
75	  };
76	}
77	
78	/**
79	 * Get manually entered revenue
80	 */
81	async function getManualRevenue(channel, period = 'month') {
82	  try {
83	    const filePath = path.join(DATA_DIR, MANUAL_REVENUE_FILE);
84	    const data = JSON.parse(await fs.readFile(filePath, 'utf-8'));
85	
86	    const now = Date.now();
87	    const periodMs = {
88	      today: 86400000,
89	      week: 604800000,
90	      month: 2592000000,
91	      all: Infinity
92	    };
93	
94	    const entries = (data[channel] || []).filter(e => {
95	      const age = now - new Date(e.date).getTime();
96	      return age <= (periodMs[period] || periodMs.month);
97	    });
98	
99	    const revenue = entries.reduce((sum, e) => sum + e.amount, 0);
100	
101	    return {
102	      revenue,
103	      transactions: entries.length,
104	      avg_order: entries.length > 0 ? revenue / entries.length : 0
105	    };
106	  } catch {
107	    return { revenue: 0, transactions: 0, avg_order: 0 };
108	  }
109	}
110	
111	/**
112	 * Add manual revenue entry
113	 */
114	export async function addManualRevenue(channel, amount, note = '') {
115	  await fs.mkdir(DATA_DIR, { recursive: true });
116	
117	  const filePath = path.join(DATA_DIR, MANUAL_REVENUE_FILE);
118	  let data = {};
119	
120	  try {
121	    data = JSON.parse(await fs.readFile(filePath, 'utf-8'));
122	  } catch {
123	    data = {};
124	  }
125	
126	  if (!data[channel]) data[channel] = [];
127	
128	  data[channel].push({
129	    date: new Date().toISOString(),
130	    amount: parseFloat(amount),
131	    note
132	  });
133	
134	  await fs.writeFile(filePath, JSON.stringify(data, null, 2));
135	
136	  return { success: true, channel, amount, total: data[channel].length };
137	}
138	
139	/**
140	 * Get revenue across all channels
141	 */
142	export async function getAllRevenue(period = 'month') {
143	  const results = {
144	    period,
145	    channels: {},
146	    total: 0,
147	    total_transactions: 0
148	  };
149	
150	  for (const [key, config] of Object.entries(CHANNELS)) {
151	    const data = await config.getRevenue(period);
152	    results.channels[key] = {
153	      name: config.name,
154	      ...data
155	    };
156	    results.total += data.revenue || 0;
157	    results.total_transactions += data.transactions || 0;
158	  }
159	
160	  results.avg_order = results.total_transactions > 0
161	    ? results.total / results.total_transactions
162	    : 0;
163	
164	  return results;
165	}
166	
167	/**
168	 * Get revenue breakdown by channel
169	 */
170	export async function getRevenueBreakdown(period = 'month') {
171	  const data = await getAllRevenue(period);
172	  const breakdown = [];
173	
174	  for (const [key, channel] of Object.entries(data.channels)) {
175	    const percentage = data.total > 0
176	      ? (channel.revenue / data.total * 100).toFixed(1)
177	      : 0;
178	
179	    breakdown.push({
180	      channel: key,
181	      name: channel.name,
182	      revenue: channel.revenue,
183	      transactions: channel.transactions,
184	      percentage: parseFloat(percentage)
185	    });
186	  }
187	
188	  return breakdown.sort((a, b) => b.revenue - a.revenue);
189	}
190	
191	/**
192	 * Track a metric
193	 */
194	export async function trackMetric(name, value, tags = {}) {
195	  await fs.mkdir(DATA_DIR, { recursive: true });
196	
197	  const date = new Date().toISOString().split('T')[0];
198	  const filePath = path.join(DATA_DIR, `metrics-${date}.json`);
199	
200	  let metrics = [];
201	  try {
202	    metrics = JSON.parse(await fs.readFile(filePath, 'utf-8'));
203	  } catch {
204	    metrics = [];
205	  }
206	
207	  metrics.push({
208	    timestamp: new Date().toISOString(),
209	    name,
210	    value,
211	    tags
212	  });
213	
214	  await fs.writeFile(filePath, JSON.stringify(metrics, null, 2));
215	}
216	
217	/**
218	 * Get daily metrics
219	 */
220	export async function getDailyMetrics(date = new Date().toISOString().split('T')[0]) {
221	  const filePath = path.join(DATA_DIR, `metrics-${date}.json`);
222	
223	  try {
224	    return JSON.parse(await fs.readFile(filePath, 'utf-8'));
225	  } catch {
226	    return [];
227	  }
228	}
229	
230	export default {
231	  getAllRevenue,
232	  getRevenueBreakdown,
233	  addManualRevenue,
234	  trackMetric,
235	  getDailyMetrics
236	};
