1	#!/usr/bin/env node
2	'use strict';
3	
4	const fs = require('fs');
5	const os = require('os');
6	const path = require('path');
7	
8	const {
9	  buildUsageSnapshot,
10	  getCacheAgeMs,
11	  hasAnthropicRuntimeOverride,
12	  hasSupportedClaudeSubscription,
13	  isUsageCacheFresh,
