23	
24	async function test(name, fn) {
25	  try {
26	    await fn();
27	    console.log(`✓ ${name}`);
28	    passed++;
29	  } catch (error) {
30	    console.log(`✗ ${name}`);
31	    console.log(`  Error: ${error.message}`);
