37	function assertEqual(actual, expected, message) {
38	  if (actual !== expected) {
39	    throw new Error(`${message}\nExpected: ${JSON.stringify(expected)}\nActual: ${JSON.stringify(actual)}`);
40	  }
41	}
42	
43	function assertTrue(condition, message) {
44	  if (!condition) {
45	    throw new Error(message);
46	  }
47	}
48	
49	function tempCachePath(label) {
50	  return path.join(os.tmpdir(), `ck-usage-cache-test-${label}-${process.pid}-${Date.now()}.json`);
51	}
52	
53	async function main() {
54	  await test('normalizeUtilization accepts live whole-number percentages and 0..1 fractions', async () => {
55	    assertEqual(normalizeUtilization(37), 37, 'Live payload percentages should be preserved');
56	    assertEqual(normalizeUtilization(0.37), 37, 'Fractional payloads should still render as percentages');
57	    assertEqual(normalizeUtilization(1), 1, 'Whole-number 1 should remain 1%, not 100%');
58	    assertEqual(normalizeUtilization(0), 0, 'Zero utilization should remain zero');
59	  });
60	
61	  await test('buildUsageSnapshot normalizes just the cosmetic 5h and wk chips', async () => {
62	    const snapshot = buildUsageSnapshot({
63	      five_hour: { utilization: 37, resets_at: '2026-04-01T00:00:00.000Z' },
64	      seven_day: { utilization: 0.19, resets_at: '2026-04-06T13:00:00.000Z' },
65	      seven_day_opus: { utilization: 55, resets_at: '2026-04-06T13:00:00.000Z' }
66	    }, new Date('2026-03-31T20:00:00.000Z').getTime());
67	
68	    assertEqual(snapshot?.fiveHourPercent, 37, '5h should preserve current whole-number percentages');
69	    assertEqual(snapshot?.weekPercent, 19, 'Weekly should still normalize fractional payloads defensively');
70	    assertTrue(!('sevenDayOpus' in snapshot), 'Cosmetic snapshot should ignore model-specific buckets');
71	  });
72	
73	  await test('runtime override detection hides quota for third-party Claude launches', async () => {
74	    assertTrue(
75	      hasAnthropicRuntimeOverride({
76	        ANTHROPIC_BASE_URL: 'http://127.0.0.1:8317/api/provider/gemini',
77	        ANTHROPIC_AUTH_TOKEN: 'ccs-managed'
