79	      'Anthropic-compatible runtime overrides should disable native quota display'
80	    );
81	    assertTrue(
82	      !hasAnthropicRuntimeOverride({ ANTHROPIC_MODEL: 'claude-sonnet-4' }),
83	      'Model-only overrides should not disable quota display'
84	    );
85	  });
86	
87	  await test('supported subscription detection accepts native Claude plans and rejects free/non-sub auth', async () => {
88	    assertTrue(
89	      hasSupportedClaudeSubscription({ claudeAiOauth: { subscriptionType: 'max' } }),
90	      'Native paid subscription types should be eligible'
91	    );
92	    assertTrue(
93	      hasSupportedClaudeSubscription({ claudeAiOauth: { rateLimitTier: 'default_claude_max_5x' } }),
94	      'Rate-limit tier should provide a defensive fallback for native Claude plans'
95	    );
96	    assertTrue(
97	      !hasSupportedClaudeSubscription({ claudeAiOauth: { subscriptionType: 'free' } }),
98	      'Free/native-non-subscription auth should not show quota chips'
99	    );
100	  });

100	  });
101	
102	  await test('resolveQuotaDisplayEligibility prioritizes runtime overrides and native subscription checks', async () => {
103	    const nativeSubCredentials = {
104	      claudeAiOauth: {
105	        accessToken: 'native-token',
106	        subscriptionType: 'max'
107	      }
108	    };
109	
110	    const overridden = resolveQuotaDisplayEligibility({
111	      env: {
112	        ANTHROPIC_BASE_URL: 'http://127.0.0.1:8317/api/provider/gemini',
113	        ANTHROPIC_AUTH_TOKEN: 'ccs-managed'
114	      },
115	      credentials: nativeSubCredentials
116	    });
117	    assertEqual(overridden.eligible, false, 'Third-party runtime override should win over local native credentials');
118	    assertEqual(overridden.note, 'runtime-override', 'Third-party runtime override should be reported clearly');
119	
120	    const freeTier = resolveQuotaDisplayEligibility({
121	      env: {},
122	      credentials: {
123	        claudeAiOauth: {
124	          accessToken: 'native-token',
125	          subscriptionType: 'free'
126	        }
127	      }
128	    });
129	    assertEqual(freeTier.eligible, false, 'Non-subscription auth should not be eligible');
130	    assertEqual(freeTier.note, 'non-subscription-auth', 'Non-subscription auth should be reported clearly');
131	  });
132	
133	  await test('refreshUsageCache writes available cache from the OAuth usage payload', async () => {
134	    const cachePath = tempCachePath('available');
135	
136	    try {
137	      const result = await refreshUsageCache({
138	        cachePath,
139	        accessToken: 'test-token',
140	        fetchImpl: async () => ({
