1	#!/usr/bin/env node
2	/**
3	 * Quota Monitor - PostToolUse Hook
4	 *
5	 * Tracks cumulative token usage per session with progressive checkpointing.
6	 * Works with startup-orchestrator for AGY co-processing and failover.
7	 *
8	 * Features:
9	 * - Token accumulation tracking
10	 * - Progressive thresholds: 50% (yellow), 70% (orange), 85% (red)
11	 * - Checkpoint file generation at each threshold
12	 * - Workload distribution signals
13	 * - AGY handoff coordination
14	 */
15	
16	const fs = require("fs");
17	const path = require("path");
18	const os = require("os");
19	
20	// Configuration
21	const TOKEN_CACHE_FILE = path.join(os.tmpdir(), "ck-startup-tokens.json");
22	const CHECKPOINT_FILE = ".startup-context.json";
23	const CONTEXT_LIMIT = 200000; // 200K tokens
24	
25	// Progressive thresholds
26	const THRESHOLDS = {
27		yellow: 0.50,  // 50% - incremental checkpoint, balance workload
28		orange: 0.70,  // 70% - full checkpoint, AGY takes primary
29		red: 0.85      // 85% - emergency checkpoint, full handoff
30	};
31	
32	// Workload distribution at each level
33	const WORKLOAD_DISTRIBUTION = {
34		green: { cc: 0.70, agy: 0.30 },   // <50%: Normal parallel
35		yellow: { cc: 0.50, agy: 0.50 },  // 50-70%: Balanced
36		orange: { cc: 0.30, agy: 0.70 },  // 70-85%: AGY primary
37		red: { cc: 0.00, agy: 1.00 }      // >85%: Full handoff
38	};
39	
40	/**
41	 * Estimate tokens from response text
42	 * Rough estimate: 1 token ≈ 4 characters
43	 */
44	function estimateTokens(text) {
45		if (!text) return 0;
46		return Math.ceil(String(text).length / 4);
47	}
48	
49	/**
50	 * Determine current zone based on usage percentage
51	 */
52	function getZone(usagePercent) {
53		if (usagePercent >= THRESHOLDS.red * 100) return "red";
54		if (usagePercent >= THRESHOLDS.orange * 100) return "orange";
55		if (usagePercent >= THRESHOLDS.yellow * 100) return "yellow";
56		return "green";
57	}
58	
59	/**
60	 * Read token accumulator
61	 */
62	function readTokenCache() {
63		try {
64			if (fs.existsSync(TOKEN_CACHE_FILE)) {
65				const cache = JSON.parse(fs.readFileSync(TOKEN_CACHE_FILE, "utf-8"));
66				// Reset if session older than 2 hours
67				if (Date.now() - cache.startTime > 7200000) {
68					return {
69						tokens: 0,
70						startTime: Date.now(),
71						zone: "green",
72						checkpoints: { yellow: false, orange: false, red: false }
73					};
74				}
75				return cache;
76			}
77		} catch {}
78		return {
79			tokens: 0,
80			startTime: Date.now(),
81			zone: "green",
82			checkpoints: { yellow: false, orange: false, red: false }
83		};
84	}
85	
86	/**
87	 * Write token accumulator
88	 */
89	function writeTokenCache(cache) {
90		try {
91			fs.writeFileSync(TOKEN_CACHE_FILE, JSON.stringify(cache));
92		} catch {}
93	}
94	
95	/**
96	 * Check if this is a startup command session
97	 */
98	function isStartupSession(input) {
99		const toolName = input?.tool_name || "";
100		const toolInput = JSON.stringify(input?.tool_input || {});
101	
102		return (
103			toolInput.includes("startup") ||
104			toolInput.includes("startup-orchestrator") ||
105			toolInput.includes("customer-obsession") ||
106			toolInput.includes("revenue-velocity") ||
107			process.env.STARTUP_SESSION === "true"
108		);
109	}
110	
111	/**
112	 * Generate checkpoint context for handoff
113	 */
114	function generateCheckpoint(cache, level) {
115		const checkpoint = {
116			level: level, // "incremental" | "full" | "emergency"
117			phase: "unknown",
118			completed: [],
119			pending: [],
120			departments: [],
121			context: {
122				query: process.env.STARTUP_QUERY || "",
123				tokens_used: cache.tokens,
124				zone: cache.zone,
125				workload: WORKLOAD_DISTRIBUTION[cache.zone]
126			},
127			timestamp: new Date().toISOString()
128		};
129	
130		try {
131			// Try to read existing checkpoint and merge
132			if (fs.existsSync(CHECKPOINT_FILE)) {
133				const existing = JSON.parse(fs.readFileSync(CHECKPOINT_FILE, "utf-8"));
134				checkpoint.phase = existing.phase || checkpoint.phase;
135				checkpoint.completed = existing.completed || [];
136				checkpoint.pending = existing.pending || [];
137				checkpoint.departments = existing.departments || [];
138				checkpoint.context = {
139					...checkpoint.context,
140					customer_discovery: existing.context?.customer_discovery,
141					revenue_velocity: existing.context?.revenue_velocity,
142					research_summary: existing.context?.research_summary,
143					department_outputs: existing.context?.department_outputs
144				};
145			}
146		} catch {}
147	
148		return checkpoint;
149	}
150	
151	/**
152	 * Write checkpoint file for AGY handoff
153	 */
154	function writeCheckpoint(checkpoint) {
155		try {
156			fs.writeFileSync(CHECKPOINT_FILE, JSON.stringify(checkpoint, null, 2));
157			return true;
158		} catch {
159			return false;
160		}
161	}
162	
163	/**
164	 * Generate zone-specific message
165	 */
166	function getZoneMessage(zone, usagePercent, tokens, checkpointWritten) {
167		const messages = {
168			yellow: `
169	🟡 **QUOTA: YELLOW ZONE** (${usagePercent.toFixed(0)}% used, ~${tokens.toLocaleString()} tokens)
170	
171	Balancing workload: CC 50% / AGY 50%
172	Incremental checkpoint saved.
173	${checkpointWritten ? "✓ Ready for AGY co-processing" : "✗ Checkpoint write failed"}
174	`,
175			orange: `
176	🟠 **QUOTA: ORANGE ZONE** (${usagePercent.toFixed(0)}% used, ~${tokens.toLocaleString()} tokens)
177	
178	AGY taking primary: CC 30% / AGY 70%
179	Full checkpoint saved.
180	${checkpointWritten ? "✓ AGY handoff ready" : "✗ Checkpoint write failed"}
181	`,
182			red: `
183	🔴 **QUOTA: RED ZONE** (${usagePercent.toFixed(0)}% used, ~${tokens.toLocaleString()} tokens)
184	
185	Full AGY handoff: CC 0% / AGY 100%
186	Emergency checkpoint saved.
187	${checkpointWritten ? "✓ Resume with \`/startup:resume\`" : "✗ Checkpoint write failed"}
188	`
189		};
190		return messages[zone] || "";
191	}
192	
193	/**
194	 * Main hook execution
195	 */
196	async function main() {
197		const result = { continue: true };
198	
199		try {
200			// Read hook input
201			let inputStr = "";
202			try {
203				inputStr = fs.readFileSync(0, "utf-8");
204			} catch {}
205	
206			const input = JSON.parse(inputStr || "{}");
207			const isStartup = isStartupSession(input);
208	
209			// Read current token accumulator
210			const cache = readTokenCache();
211	
212			// Estimate tokens from tool response
213			const toolOutput = input?.tool_output || "";
214			const toolInput = JSON.stringify(input?.tool_input || {});
215			const newTokens = estimateTokens(toolOutput) + estimateTokens(toolInput);
216	
217			// Accumulate
218			cache.tokens += newTokens;
219	
220			// Check zone
221			const usagePercent = (cache.tokens / CONTEXT_LIMIT) * 100;
222			const newZone = getZone(usagePercent);
223			const oldZone = cache.zone;
224	
225			// Update zone
226			cache.zone = newZone;
227	
228			// Check if we crossed a threshold
229			let checkpointLevel = null;
230			let shouldNotify = false;
231	
232			if (newZone === "yellow" && !cache.checkpoints.yellow) {
233				cache.checkpoints.yellow = true;
234				checkpointLevel = "incremental";
235				shouldNotify = true;
236			} else if (newZone === "orange" && !cache.checkpoints.orange) {
237				cache.checkpoints.orange = true;
238				checkpointLevel = "full";
239				shouldNotify = true;
240			} else if (newZone === "red" && !cache.checkpoints.red) {
241				cache.checkpoints.red = true;
242				checkpointLevel = "emergency";
243				shouldNotify = true;
244			}
245	
246			// Generate checkpoint if threshold crossed
247			if (shouldNotify && checkpointLevel) {
248				const checkpoint = generateCheckpoint(cache, checkpointLevel);
249				const checkpointWritten = writeCheckpoint(checkpoint);
250	
251				// Set environment variables for orchestrator
252				process.env.QUOTA_ZONE = newZone;
253				process.env.QUOTA_WORKLOAD_CC = String(WORKLOAD_DISTRIBUTION[newZone].cc);
254				process.env.QUOTA_WORKLOAD_AGY = String(WORKLOAD_DISTRIBUTION[newZone].agy);
255	
256				// Only output message for startup sessions
257				if (isStartup) {
258					result.message = getZoneMessage(newZone, usagePercent, cache.tokens, checkpointWritten);
259				}
260			}
261	
262			// Write updated cache
263			writeTokenCache(cache);
264	
265		} catch (err) {
266			// Silent fail, don't block tool execution
267		}
268	
269		console.log(JSON.stringify(result));
270	}
271	
272	main().catch(() => {
273		console.log(JSON.stringify({ continue: true }));
274		process.exit(0);
275	});
